import java.util.Scanner;

public class ShowRoomBill {
    private String name;
    private long mobno;
    private double cost;
    private double dis;
    private double amount;

    public ShowRoomBill() {
        name = "";
        mobno = 0L;
        cost = 0.0;
        dis = 0.0;
        amount = 0.0;
    }

    public void input() {
        Scanner in = new Scanner(System.in);
        System.out.print("Enter Customer Name: ");
        name = in.nextLine();
        System.out.print("Enter Mobile Number: ");
        mobno = in.nextLong();
        System.out.print("Enter Total Purchase Cost (Rs): ");
        cost = in.nextDouble();
    }

    public void calculate() {
        double rate;
        if (cost <= 10000.0) {
            rate = 0.05;
        } else if (cost <= 20000.0) {
            rate = 0.10;
        } else if (cost <= 35000.0) {
            rate = 0.15;
        } else {
            rate = 0.20;
        }

        dis = cost * rate;
        amount = cost - dis;
    }

    public void display() {
        System.out.println("\n============== SHOWROOM INVOICE ==============");
        System.out.println("Customer Name       : " + name);
        System.out.println("Mobile Number       : " + mobno);
        System.out.println("Gross Purchase Cost : Rs. " + cost);
        System.out.println("Discount Allowed    : Rs. " + dis);
        System.out.println("Net Payable Amount  : Rs. " + amount);
        System.out.println("================================================");
    }

    public static void main(String[] args) {
        ShowRoomBill invoice = new ShowRoomBill();
        invoice.input();
        invoice.calculate();
        invoice.display();
    }
}
```

