import java.util.Scanner;

public class SelectionSortAscending {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        final int N = 10;
        int[] arr = new int[N];

        System.out.println("Enter " + N + " integers for Selection Sort:");
        for (int i = 0; i < N; i++) {
            System.out.print("Element [" + i + "]: ");
            arr[i] = sc.nextInt();
        }

        System.out.println("\nOriginal Array:");
        for (int val : arr) {
            System.out.print(val + " ");
        }
        System.out.println();

        // Selection Sort Algorithm
        for (int i = 0; i < N - 1; i++) {
            int minIdx = i;
            for (int j = i + 1; j < N; j++) {
                if (arr[j] < arr[minIdx]) {
                    minIdx = j;
                }
            }
            // Swap smallest found with arr[i]
            if (minIdx != i) {
                int temp = arr[i];
                arr[i] = arr[minIdx];
                arr[minIdx] = temp;
            }
        }

        System.out.println("\nSorted Array (Ascending Order):");
        for (int val : arr) {
            System.out.print(val + " ");
        }
        System.out.println();
    }
}
```

