import java.util.Scanner;

public class NameInitialsSurname {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        System.out.println("Enter full name (First Middle Surname):");
        String fullName = in.nextLine().trim();

        int lastSpaceIndex = fullName.lastIndexOf(' ');
        if (lastSpaceIndex == -1) {
            // Only a single word entered
            System.out.println("Formatted Name: " + fullName);
            return;
        }

        String surname = fullName.substring(lastSpaceIndex + 1);
        String nameWithoutSurname = fullName.substring(0, lastSpaceIndex).trim();

        // Print initial of first name
        String formatted = "";
        formatted += Character.toUpperCase(nameWithoutSurname.charAt(0)) + ". ";

        // Look for subsequent spaces to grab next initials
        for (int i = 0; i < nameWithoutSurname.length(); i++) {
            if (nameWithoutSurname.charAt(i) == ' ' && i + 1 < nameWithoutSurname.length()) {
                if (nameWithoutSurname.charAt(i + 1) != ' ') {
                    formatted += Character.toUpperCase(nameWithoutSurname.charAt(i + 1)) + ". ";
                }
            }
        }

        formatted += surname;
        System.out.println("\nOriginal Name : " + fullName);
        System.out.println("Formatted Name: " + formatted);
    }
}
```

