import java.util.Scanner;

public class IdentityMatrixCheck {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        final int SIZE = 4;
        int[][] mat = new int[SIZE][SIZE];

        System.out.println("Enter elements for a " + SIZE + "x" + SIZE + " matrix:");
        for (int i = 0; i < SIZE; i++) {
            for (int j = 0; j < SIZE; j++) {
                mat[i][j] = in.nextInt();
            }
        }

        System.out.println("\nMatrix entered:");
        for (int i = 0; i < SIZE; i++) {
            for (int j = 0; j < SIZE; j++) {
                System.out.printf("%3d", mat[i][j]);
            }
            System.out.println();
        }

        boolean isIdentity = true;
        for (int i = 0; i < SIZE; i++) {
            for (int j = 0; j < SIZE; j++) {
                if (i == j) {
                    if (mat[i][j] != 1) {
                        isIdentity = false;
                        break;
                    }
                } else {
                    if (mat[i][j] != 0) {
                        isIdentity = false;
                        break;
                    }
                }
            }
            if (!isIdentity) break;
        }

        System.out.println();
        if (isIdentity) {
            System.out.println("The given matrix is an IDENTITY MATRIX.");
        } else {
            System.out.println("The given matrix is NOT an Identity Matrix.");
        }
    }
}
```

