public class OverloadPattern {
    // Overload 1: Number triangle
    public void pattern(int n) {
        System.out.println("Number Triangle (n = " + n + "):");
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= i; j++) {
                System.out.print(j + " ");
            }
            System.out.println();
        }
    }

    // Overload 2: Inverted character triangle
    public void pattern(char ch, int lines) {
        System.out.println("Inverted Character Triangle ('" + ch + "', lines = " + lines + "):");
        for (int i = lines; i >= 1; i--) {
            for (int j = 1; j <= i; j++) {
                System.out.print(ch + " ");
            }
            System.out.println();
        }
    }

    public static void main(String[] args) {
        OverloadPattern printer = new OverloadPattern();

        printer.pattern(5);
        System.out.println();
        printer.pattern('*', 4);
    }
}
```

